PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS universities (id TEXT PRIMARY KEY, name TEXT NOT NULL, allowed_email_domains TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, university_id TEXT NOT NULL REFERENCES universities(id), university_email TEXT NOT NULL UNIQUE, university_verified_at TEXT, account_status TEXT NOT NULL DEFAULT 'active' CHECK(account_status IN ('active','suspended')), is_demo INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS academic_programs (id TEXT PRIMARY KEY, university_id TEXT NOT NULL REFERENCES universities(id), name TEXT NOT NULL, UNIQUE(university_id,name));
CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, first_name TEXT NOT NULL, last_name TEXT NOT NULL, major_program_id TEXT NOT NULL REFERENCES academic_programs(id), minor_program_id TEXT REFERENCES academic_programs(id), graduation_year INTEGER, bio TEXT NOT NULL DEFAULT '', avatar_style INTEGER NOT NULL DEFAULT 0, instagram_url TEXT, linkedin_url TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tags (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS profile_tags (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, tag_id TEXT NOT NULL REFERENCES tags(id), kind TEXT NOT NULL DEFAULT 'interest' CHECK(kind IN ('interest','hobby')), PRIMARY KEY(user_id,tag_id));
CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, university_id TEXT NOT NULL REFERENCES universities(id), name TEXT NOT NULL, kind TEXT NOT NULL, UNIQUE(university_id,name));
CREATE TABLE IF NOT EXISTS profile_organizations (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, organization_id TEXT NOT NULL REFERENCES organizations(id), PRIMARY KEY(user_id,organization_id));
CREATE TABLE IF NOT EXISTS experiences (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, organization_name TEXT NOT NULL DEFAULT '', time_label TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS visibility_settings (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, audience TEXT NOT NULL DEFAULT 'nobody' CHECK(audience IN ('university','connections','nobody')), visible_until TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_locations (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, latitude REAL NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude REAL NOT NULL CHECK(longitude BETWEEN -180 AND 180), accuracy_meters REAL, received_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS connections (user_low_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, user_high_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, requested_by TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL CHECK(status IN ('pending','accepted')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, accepted_at TEXT, PRIMARY KEY(user_low_id,user_high_id), CHECK(user_low_id < user_high_id), CHECK(requested_by IN (user_low_id,user_high_id)));
CREATE TABLE IF NOT EXISTS blocks (blocker_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, blocked_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id <> blocked_id));
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, reporter_id TEXT REFERENCES users(id) ON DELETE SET NULL, reported_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, reason TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','reviewed','dismissed')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS connections_recipient ON connections(user_high_id,status);
CREATE INDEX IF NOT EXISTS blocks_target ON blocks(blocked_id);
CREATE INDEX IF NOT EXISTS users_campus ON users(university_id,account_status);
